CREATE TABLE commerce_contract_templates (id uuid PRIMARY KEY, company_id uuid NOT NULL, name text NOT NULL, body text NOT NULL, version bigint NOT NULL CHECK(version >= 1), created_by uuid NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX commerce_contract_templates_company_idx ON commerce_contract_templates(company_id, updated_at DESC);
CREATE TABLE commerce_contract_versions (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES commerce_orders, company_id uuid NOT NULL, template_id uuid REFERENCES commerce_contract_templates, template_version bigint, prior_signed_version_id uuid REFERENCES commerce_contract_versions, kind text NOT NULL CHECK(kind IN ('contract','amendment')), state text NOT NULL CHECK(state IN ('draft','signed')), reference text NOT NULL DEFAULT '', signed_on date, external_file_ids jsonb NOT NULL DEFAULT '[]', signed_file_ids jsonb NOT NULL DEFAULT '[]', content text NOT NULL DEFAULT '', party_snapshot jsonb NOT NULL, terms_snapshot jsonb NOT NULL, terms_digest text NOT NULL, source_order_revision bigint NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version bigint NOT NULL CHECK(version >= 1));
CREATE INDEX commerce_contract_versions_order_idx ON commerce_contract_versions(order_id, created_at, id);
CREATE INDEX commerce_contract_versions_company_order_idx ON commerce_contract_versions(company_id, order_id, created_at, id);
CREATE UNIQUE INDEX commerce_contract_versions_base_signed_once ON commerce_contract_versions(order_id) WHERE kind = 'contract' AND state = 'signed';
